sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float threshold;
uniform float highThreshold;
uniform float softness;
uniform float weighted;
uniform float invert;
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    float3 rgb = unpremul(c).rgb;
    float lum = weighted > 0.5 ? dot(rgb, float3(0.2126, 0.7152, 0.0722)) : dot(rgb, float3(0.3333, 0.3334, 0.3333));
    float lowA = clamp(threshold - softness * 0.5, 0.0, 1.0);
    float lowB = clamp(lowA + softness, 0.0, 1.0);
    float highA = clamp(highThreshold - softness * 0.5, 0.0, 1.0);
    float highB = clamp(highA + softness, 0.0, 1.0);
    float keep = min(smoothstep(lowA, lowB, lum), 1.0 - smoothstep(highA, highB, lum));
    if (invert > 0.5) keep = 1.0 - keep;
    return c * keep;
}
